index 00000000..54677aa6
--- /dev/null
+++ b/src/kded/mediaplayerexporter.cpp
@@ -0,0 +1,54 @@
+/*
+ *   SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+ *
+ *   SPDX-License-Identifier: GPL-2.0-or-later
+ */
+
+#include "mediaplayerexporter.h"
+#include "bluedevildaemon.h"
+#include "mprisplayer.h"
+
+#include <BluezQt/Device>
+#include <BluezQt/Manager>
+
+MediaPlayerExporter::MediaPlayerExporter(BlueDevilDaemon *daemon)
+    : QObject(daemon)
+    , m_manager(daemon->manager())
+{
+    for (const BluezQt::DevicePtr &device : m_manager->devices()) {
+        deviceAdded(device);
+    }
+
+    connect(m_manager, &BluezQt::Manager::deviceAdded, this, &MediaPlayerExporter::deviceAdded);
+    connect(m_manager, &BluezQt::Manager::deviceRemoved, this, &MediaPlayerExporter::deviceRemoved);
+}
+
+void MediaPlayerExporter::deviceAdded(BluezQt::DevicePtr device)
+{
+    BluezQt::Device *d = device.data();
+    connect(d, &BluezQt::Device::mediaPlayerChanged, this, [this, d] {
+        updatePlayer(d->toSharedPtr());
+    });
+    updatePlayer(device);
+}
+
+void MediaPlayerExporter::deviceRemoved(BluezQt::DevicePtr device)
+{
+    delete m_players.take(device->ubi());
+}
+
+void MediaPlayerExporter::updatePlayer(BluezQt::DevicePtr device)
+{
+    MprisPlayer *mprisPlayer = m_players.value(device->ubi());
+    if (mprisPlayer && mprisPlayer->player() == device->mediaPlayer()) {
+        return;
+    }
+
+    delete m_players.take(device->ubi());
+
+    if (device->mediaPlayer()) {
+        m_players.insert(device->ubi(), new MprisPlayer(device, device->mediaPlayer(), this));
+    }
+}
+
+#include "moc_mediaplayerexporter.cpp"
