+
+class BlueDevilDaemon;
+class MprisPlayer;
+
+// Exports the media players of connected devices (AVRCP) as MPRIS players
+class MediaPlayerExporter : public QObject
+{
+    Q_OBJECT
+
+public:
+    explicit MediaPlayerExporter(BlueDevilDaemon *daemon);
+
+private:
+    void deviceAdded(BluezQt::DevicePtr device);
+    void deviceRemoved(BluezQt::DevicePtr device);
+    void updatePlayer(BluezQt::DevicePtr device);
+
+    BluezQt::Manager *m_manager;
+    QHash<QString, MprisPlayer *> m_players;
+};
diff --git a/src/kded/mprisplayer.cpp b/src/kded/mprisplayer.cpp
new file mode 100644
index 00000000..e2e722ae
--- /dev/null
+++ b/src/kded/mprisplayer.cpp
@@ -0,0 +1,256 @@
+/*
+ *   SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+ *
+ *   SPDX-License-Identifier: GPL-2.0-or-later
+ */
+
+#include "mprisplayer.h"
+#include "bluedevil_kded.h"
+
+#include <QDBusMessage>
+
+#include <BluezQt/Device>
+#include <BluezQt/MediaPlayer>
+#include <BluezQt/MediaPlayerTrack>
+
+static const QString s_objectPath = QStringLiteral("/org/mpris/MediaPlayer2");
+static const QString s_playerInterface = QStringLiteral("org.mpris.MediaPlayer2.Player");
+
+MprisPlayer::MprisPlayer(BluezQt::DevicePtr device, BluezQt::MediaPlayerPtr player, QObject *parent)
+    : QObject(parent)
+    , m_device(device)
+    , m_player(player)
+    , m_connection(QDBusConnection::connectToBus(QDBusConnection::SessionBus, QStringLiteral("bluedevil-mpris-") + device->ubi()))
+    , m_serviceName(QStringLiteral("org.mpris.MediaPlayer2.bluedevil.dev_") + device->address().replace(QLatin1Char(':'), QLatin1Char('_')))
+{
+    new MprisRootAdaptor(this);
+    auto playerAdaptor = new MprisPlayerAdaptor(this);
+
+    connect(m_device.data(), &BluezQt::Device::nameChanged, this, [this] {
+        propertiesChanged(QStringLiteral("org.mpris.MediaPlayer2"), {{QStringLiteral("Identity"), m_device->name()}});
+    });
+    connect(m_player.data(), &BluezQt::MediaPlayer::statusChanged, this, [this] {
+        propertiesChanged(s_playerInterface, {{QStringLiteral("PlaybackStatus"), playbackStatus()}});
+    });
+    connect(m_player.data(), &BluezQt::MediaPlayer::trackChanged, this, [this] {
+        ++m_trackNumber;
+        propertiesChanged(s_playerInterface, {{QStringLiteral("Metadata"), metadata()}});
+    });
+    connect(m_player.data(), &BluezQt::MediaPlayer::positionChanged, playerAdaptor, [this, playerAdaptor] {
+        Q_EMIT playerAdaptor->Seeked(position());
+    });
+
+    if (!m_connection.registerObject(s_objectPath, this, QDBusConnection::ExportAdaptors) || !m_connection.registerService(m_serviceName)) {
+        qCWarning(BLUEDEVIL_KDED_LOG) << "Cannot export media player of" << m_device->address() << "as" << m_serviceName << m_connection.lastError().message();
+    }
+}
+
+MprisPlayer::~MprisPlayer()
+{
+    m_connection.unregisterService(m_serviceName);
+    m_connection.unregisterObject(s_objectPath);
+    QDBusConnection::disconnectFromBus(m_connection.name());
+}
+
+BluezQt::DevicePtr MprisPlayer::device() const
+{
+    return m_device;
+}
+
+BluezQt::MediaPlayerPtr MprisPlayer::player() const
+{
+    return m_player;
+}
+
+QString MprisPlayer::playbackStatus() const
+{
+    switch (m_player->status()) {
+    case BluezQt::MediaPlayer::Playing:
+    case BluezQt::MediaPlayer::ForwardSeek:
+    case BluezQt::MediaPlayer::ReverseSeek:
+        return QStringLiteral("Playing");
+    case BluezQt::MediaPlayer::Paused:
+        return QStringLiteral("Paused");
+    default:
+        return QStringLiteral("Stopped");
+    }
+}
+
+QVariantMap MprisPlayer::metadata() const
+{
+    const BluezQt::MediaPlayerTrack track = m_player->track();
+    if (!track.isValid()) {
+        return {{QStringLiteral("mpris:trackid"), QVariant::fromValue(QDBusObjectPath(QStringLiteral("/org/mpris/MediaPlayer2/TrackList/NoTrack")))}};
+    }
+
+    QVariantMap metadata{
+        {QStringLiteral("mpris:trackid"), QVariant::fromValue(QDBusObjectPath(QStringLiteral("/org/kde/bluedevil/track/%1").arg(m_trackNumber)))},
+        {QStringLiteral("xesam:title"), track.title()},
+    };
+    if (!track.artist().isEmpty()) {
+        metadata.insert(QStringLiteral("xesam:artist"), QStringList{track.artist()});
+    }
+    if (!track.album().isEmpty()) {
+        metadata.insert(QStringLiteral("xesam:album"), track.album());
+    }
+    if (!track.genre().isEmpty()) {
+        metadata.insert(QStringLiteral("xesam:genre"), QStringList{track.genre()});
+    }
+    if (track.trackNumber() > 0) {
+        metadata.insert(QStringLiteral("xesam:trackNumber"), int(track.trackNumber()));
+    }
+    if (track.duration() > 0) {
+        metadata.insert(QStringLiteral("mpris:length"), qlonglong(track.duration()) * 1000);
+    }
+    return metadata;
+}
+
+qlonglong MprisPlayer::position() const
+{
+    // BlueZ uses milliseconds, MPRIS microseconds
+    return qlonglong(m_player->position()) * 1000;
+}
+
+void MprisPlayer::propertiesChanged(const QString &interface, const QVariantMap &properties)
+{
+    QDBusMessage message = QDBusMessage::createSignal(s_objectPath, QStringLiteral("org.freedesktop.DBus.Properties"), QStringLiteral("PropertiesChanged"));
+    message.setArguments({interface, properties, QStringList()});
+    m_connection.send(message);
+}
+
+MprisRootAdaptor::MprisRootAdaptor(MprisPlayer *parent)
+    : QDBusAbstractAdaptor(parent)
+    , m_player(parent)
+{
+}
+
+bool MprisRootAdaptor::canQuit() const
+{
+    return false;
+}
+
+bool MprisRootAdaptor::canRaise() const
+{
+    return false;
+}
+
+bool MprisRootAdaptor::hasTrackList() const
+{
+    return false;
+}
+
+QString MprisRootAdaptor::identity() const
+{
+    return m_player->device()->name();
+}
+
+QStringList MprisRootAdaptor::supportedUriSchemes() const
+{
+    return {};
+}
+
+QStringList MprisRootAdaptor::supportedMimeTypes() const
+{
+    return {};
+}
+
+void MprisRootAdaptor::Raise()
+{
+}
+
+void MprisRootAdaptor::Quit()
+{
+}
+
+MprisPlayerAdaptor::MprisPlayerAdaptor(MprisPlayer *parent)
+    : QDBusAbstractAdaptor(parent)
+    , m_player(parent)
+{
+}
+
+QString MprisPlayerAdaptor::playbackStatus() const
+{
+    return m_player->playbackStatus();
+}
+
+double MprisPlayerAdaptor::rate() const
+{
+    return 1.0;
+}
+
+void MprisPlayerAdaptor::setRate(double rate)
+{
+    Q_UNUSED(rate)
+}
+
+QVariantMap MprisPlayerAdaptor::metadata() const
+{
+    return m_player->metadata();
+}
+
+qlonglong MprisPlayerAdaptor::position() const
+{
+    return m_player->position();
+}
+
+bool MprisPlayerAdaptor::canSeek() const
+{
+    return false;
+}
+
+bool MprisPlayerAdaptor::canControl() const
+{
+    return true;
+}
+
+void MprisPlayerAdaptor::Next()
+{
+    m_player->player()->next();
+}
+
+void MprisPlayerAdaptor::Previous()
+{
+    m_player->player()->previous();
+}
+
+void MprisPlayerAdaptor::Pause()
+{
+    m_player->player()->pause();
+}
+
+void MprisPlayerAdaptor::PlayPause()
+{
+    if (m_player->player()->status() == BluezQt::MediaPlayer::Playing) {
+        m_player->player()->pause();
+    } else {
+        m_player->player()->play();
+    }
+}
+
+void MprisPlayerAdaptor::Stop()
+{
+    m_player->player()->stop();
+}
+
+void MprisPlayerAdaptor::Play()
+{
+    m_player->player()->play();
+}
+
+void MprisPlayerAdaptor::Seek(qlonglong offset)
+{
+    Q_UNUSED(offset)
+}
+
+void MprisPlayerAdaptor::SetPosition(const QDBusObjectPath &trackId, qlonglong position)
+{
+    Q_UNUSED(trackId)
+    Q_UNUSED(position)
+}
+
+void MprisPlayerAdaptor::OpenUri(const QString &uri)
+{
+    Q_UNUSED(uri)
+}
+
+#include "moc_mprisplayer.cpp"
