@@ -0,0 +1,119 @@
+/*
+ *   SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+ *
+ *   SPDX-License-Identifier: GPL-2.0-or-later
+ */
+
+#pragma once
+
+#include <QDBusAbstractAdaptor>
+#include <QDBusConnection>
+#include <QDBusObjectPath>
+#include <QStringList>
+#include <QVariantMap>
+
+#include <BluezQt/Types>
+
+// MPRIS player for the media player of a Bluetooth device. Each one has its own
+// session bus connection, as all MPRIS players live at /org/mpris/MediaPlayer2
+class MprisPlayer : public QObject
+{
+    Q_OBJECT
+
+public:
+    explicit MprisPlayer(BluezQt::DevicePtr device, BluezQt::MediaPlayerPtr player, QObject *parent);
+    ~MprisPlayer() override;
+
+    BluezQt::DevicePtr device() const;
+    BluezQt::MediaPlayerPtr player() const;
+
+    QString playbackStatus() const;
+    QVariantMap metadata() const;
+    qlonglong position() const;
+
+    void propertiesChanged(const QString &interface, const QVariantMap &properties);
+
+private:
+    BluezQt::DevicePtr m_device;
+    BluezQt::MediaPlayerPtr m_player;
+    QDBusConnection m_connection;
+    QString m_serviceName;
+    quint32 m_trackNumber = 0;
+};
+
+class MprisRootAdaptor : public QDBusAbstractAdaptor
+{
+    Q_OBJECT
+    Q_CLASSINFO("D-Bus Interface", "org.mpris.MediaPlayer2")
+
+    Q_PROPERTY(bool CanQuit READ canQuit)
+    Q_PROPERTY(bool CanRaise READ canRaise)
+    Q_PROPERTY(bool HasTrackList READ hasTrackList)
+    Q_PROPERTY(QString Identity READ identity)
+    Q_PROPERTY(QStringList SupportedUriSchemes READ supportedUriSchemes)
+    Q_PROPERTY(QStringList SupportedMimeTypes READ supportedMimeTypes)
+
+public:
+    explicit MprisRootAdaptor(MprisPlayer *parent);
+
+    bool canQuit() const;
+    bool canRaise() const;
+    bool hasTrackList() const;
+    QString identity() const;
+    QStringList supportedUriSchemes() const;
+    QStringList supportedMimeTypes() const;
+
+public Q_SLOTS:
+    void Raise();
+    void Quit();
+
+private:
+    MprisPlayer *m_player;
+};
+
+class MprisPlayerAdaptor : public QDBusAbstractAdaptor
+{
+    Q_OBJECT
+    Q_CLASSINFO("D-Bus Interface", "org.mpris.MediaPlayer2.Player")
+
+    Q_PROPERTY(QString PlaybackStatus READ playbackStatus)
+    Q_PROPERTY(double Rate READ rate WRITE setRate)
+    Q_PROPERTY(QVariantMap Metadata READ metadata)
+    Q_PROPERTY(qlonglong Position READ position)
+    Q_PROPERTY(double MinimumRate READ rate)
+    Q_PROPERTY(double MaximumRate READ rate)
+    Q_PROPERTY(bool CanGoNext READ canControl)
+    Q_PROPERTY(bool CanGoPrevious READ canControl)
+    Q_PROPERTY(bool CanPlay READ canControl)
+    Q_PROPERTY(bool CanPause READ canControl)
+    Q_PROPERTY(bool CanSeek READ canSeek)
+    Q_PROPERTY(bool CanControl READ canControl)
+
+public:
+    explicit MprisPlayerAdaptor(MprisPlayer *parent);
+
+    QString playbackStatus() const;
+    double rate() const;
+    void setRate(double rate);
+    QVariantMap metadata() const;
+    qlonglong position() const;
+    bool canSeek() const;
+    bool canControl() const;
+
+public Q_SLOTS:
+    void Next();
+    void Previous();
+    void Pause();
+    void PlayPause();
+    void Stop();
+    void Play();
+    void Seek(qlonglong offset);
+    void SetPosition(const QDBusObjectPath &trackId, qlonglong position);
+    void OpenUri(const QString &uri);
+
+Q_SIGNALS:
+    void Seeked(qlonglong position);
+
+private:
+    MprisPlayer *m_player;
+};
